import 'reflect-metadata';
import { plainToInstance } from 'class-transformer';
import { validate } from 'class-validator';
import { CreateBookingDto } from './create-booking.dto';

const validBody = {
  roomId: '3f0c1a52-8f0b-4c59-9a6e-1d2b7c9e4a10',
  title: 'Sprint planning',
  organizerEmail: 'organizer@example.com',
  startsAt: '2030-01-07T09:00:00.000Z',
  endsAt: '2030-01-07T10:00:00.000Z',
};

const errorsFor = async (plain: Record<string, unknown>): Promise<string[]> => {
  const errors = await validate(plainToInstance(CreateBookingDto, plain));
  return errors.map((error) => error.property);
};

describe('CreateBookingDto', () => {
  it('accepts a valid body', async () => {
    expect(await errorsFor(validBody)).toEqual([]);
  });

  it.each([
    ['roomId', 'not-a-uuid'],
    ['title', ''],
    ['title', 'x'.repeat(121)],
    ['organizerEmail', 'not-an-email'],
    ['startsAt', '07/01/2030 09:00'],
    ['endsAt', 'tomorrow'],
  ])('rejects an invalid %s', async (property, value) => {
    expect(await errorsFor({ ...validBody, [property]: value })).toEqual([property]);
  });

  it('rejects a missing field', async () => {
    expect(await errorsFor({ ...validBody, title: undefined })).toEqual(['title']);
  });
});
import { IsEmail, IsISO8601, IsString, IsUUID, Length } from 'class-validator';
import { BOOKING_TITLE_MAX_LENGTH } from '../contract.constants';

export class CreateBookingDto {
  @IsUUID()
  roomId: string;

  @IsString()
  @Length(1, BOOKING_TITLE_MAX_LENGTH)
  title: string;

  @IsEmail()
  organizerEmail: string;

  @IsISO8601({ strict: true })
  startsAt: string;

  @IsISO8601({ strict: true })
  endsAt: string;
}
export class ErrorResponseDto {
  statusCode: number;
  errorCode: string;
  message: string;
}
import { IsOptional, IsUUID } from 'class-validator';
import { PageQueryDto } from './page-query.dto';

export class ListBookingsQueryDto extends PageQueryDto {
  @IsOptional()
  @IsUUID()
  roomId?: string;
}
import 'reflect-metadata';
import { plainToInstance } from 'class-transformer';
import { validate } from 'class-validator';
import { PageQueryDto } from './page-query.dto';

const errorsFor = async (plain: Record<string, unknown>): Promise<string[]> => {
  const errors = await validate(plainToInstance(PageQueryDto, plain));
  return errors.map((error) => error.property);
};

describe('PageQueryDto', () => {
  it('defaults to page 1 with 10 items', async () => {
    const dto = plainToInstance(PageQueryDto, {});

    expect(await validate(dto)).toHaveLength(0);
    expect(dto.page).toBe(1);
    expect(dto.limit).toBe(10);
  });

  it('converts query strings to numbers', async () => {
    const dto = plainToInstance(PageQueryDto, { page: '2', limit: '5' });

    expect(await validate(dto)).toHaveLength(0);
    expect(dto.page).toBe(2);
    expect(dto.limit).toBe(5);
  });

  it.each([
    [{ page: 0 }, 'page'],
    [{ page: -1 }, 'page'],
    [{ page: '1.5' }, 'page'],
    [{ limit: 0 }, 'limit'],
    [{ limit: 101 }, 'limit'],
    [{ limit: 'abc' }, 'limit'],
  ])('rejects %j', async (plain, property) => {
    expect(await errorsFor(plain)).toEqual([property]);
  });
});
import { Type } from 'class-transformer';
import { IsInt, Max, Min } from 'class-validator';
import { DEFAULT_PAGE_SIZE, MAX_PAGE_SIZE } from '../contract.constants';

export class PageQueryDto {
  @Type(() => Number)
  @IsInt()
  @Min(1)
  page = 1;

  @Type(() => Number)
  @IsInt()
  @Min(1)
  @Max(MAX_PAGE_SIZE)
  limit = DEFAULT_PAGE_SIZE;
}
import { IsUUID } from 'class-validator';

export class RoomDto {
  id: string;
  name: string;
  capacity: number;
}

export class PagedRoomsDto {
  items: RoomDto[];
  total: number;
  page: number;
  limit: number;
}

export class RoomIdMessageDto {
  @IsUUID()
  id: string;
}
import { IsISO8601, IsOptional, IsString, Length } from 'class-validator';
import { BOOKING_TITLE_MAX_LENGTH } from '../contract.constants';

export class UpdateBookingDto {
  @IsOptional()
  @IsString()
  @Length(1, BOOKING_TITLE_MAX_LENGTH)
  title?: string;

  @IsOptional()
  @IsISO8601({ strict: true })
  startsAt?: string;

  @IsOptional()
  @IsISO8601({ strict: true })
  endsAt?: string;
}

