import { INestApplication, ValidationPipe } from '@nestjs/common';
import { HttpAdapterHost } from '@nestjs/core';
import { RpcExceptionFilter } from '@roombook/backend-common';

export const GATEWAY_GLOBAL_PREFIX = 'api';

export const configureGatewayApp = (app: INestApplication): void => {
  app.setGlobalPrefix(GATEWAY_GLOBAL_PREFIX);
  app.useGlobalPipes(new ValidationPipe({ transform: true, whitelist: true }));
  app.useGlobalFilters(new RpcExceptionFilter(app.get(HttpAdapterHost).httpAdapter));
};
import { Controller, Get, Inject, Query } from '@nestjs/common';
import { ClientProxy } from '@nestjs/microservices';
import { NATS_CLIENT, NatsRequestUtil } from '@roombook/backend-common';
import { ApiRouteEnum, PagedRoomsDto, PageQueryDto, RoomPatternEnum } from '@roombook/contract';

@Controller(ApiRouteEnum.ROOMS)
export class RoomController {
  constructor(@Inject(NATS_CLIENT) private readonly client: ClientProxy) {}

  @Get()
  listRooms(@Query() query: PageQueryDto): Promise<PagedRoomsDto> {
    return NatsRequestUtil.send<PagedRoomsDto, PageQueryDto>(this.client, RoomPatternEnum.LIST, query);
  }
}
import { Module } from '@nestjs/common';
import { RoomController } from './room.controller';

@Module({
  controllers: [RoomController],
})
export class RoomModule {}
export * from './lib/config/database-env.schema';
export * from './lib/config/nats-options';
export * from './lib/config/redis-connection.config';
export * from './lib/config/typeorm-config.service';
export * from './lib/entities/room.entity';
export * from './lib/errors/exception.helper';
export * from './lib/errors/rpc-exception.filter';
export * from './lib/health/health.service';
export * from './lib/nats/nats-client.module';
export * from './lib/nats/nats-request.util';
import { HttpStatus } from '@nestjs/common';
import { RpcException } from '@nestjs/microservices';
import { ErrorCodeEnum, ErrorResponseDto } from '@roombook/contract';

export class ExceptionHelper {
  static badRequest(errorCode: ErrorCodeEnum, message: string): never {
    return ExceptionHelper.raise(HttpStatus.BAD_REQUEST, errorCode, message);
  }

  static notFound(errorCode: ErrorCodeEnum, message: string): never {
    return ExceptionHelper.raise(HttpStatus.NOT_FOUND, errorCode, message);
  }

  static conflict(errorCode: ErrorCodeEnum, message: string): never {
    return ExceptionHelper.raise(HttpStatus.CONFLICT, errorCode, message);
  }

  static unprocessable(errorCode: ErrorCodeEnum, message: string): never {
    return ExceptionHelper.raise(HttpStatus.UNPROCESSABLE_ENTITY, errorCode, message);
  }

  static serviceUnavailable(errorCode: ErrorCodeEnum, message: string): never {
    return ExceptionHelper.raise(HttpStatus.SERVICE_UNAVAILABLE, errorCode, message);
  }

  private static raise(statusCode: HttpStatus, errorCode: ErrorCodeEnum, message: string): never {
    const error: ErrorResponseDto = { statusCode, errorCode, message };
    throw new RpcException(error);
  }
}
import { ArgumentsHost, BadRequestException, Catch, HttpStatus } from '@nestjs/common';
import { BaseExceptionFilter } from '@nestjs/core';
import { RpcException } from '@nestjs/microservices';
import { ErrorCodeEnum, ErrorResponseDto } from '@roombook/contract';

const isErrorResponse = (value: unknown): value is ErrorResponseDto => {
  if (typeof value !== 'object' || value === null) {
    return false;
  }
  const candidate = value as Record<string, unknown>;
  return (
