tool_input.command:
node -e '
require("reflect-metadata");
const { ValidationPipe } = require("@nestjs/common");
const { IsOptional, IsString } = require("class-validator");
class Dto {}
IsOptional()(Dto.prototype, "title"); IsString()(Dto.prototype, "title");
const meta = { type: "body", metatype: Dto };
const globalPipe = new ValidationPipe({ transform: true, whitelist: true });
const handlerPipe = new ValidationPipe({ transform: true, whitelist: true, forbidNonWhitelisted: true });
(async () => {
  const body = { title: "x", roomId: "r" };
  const afterGlobal = await globalPipe.transform(body, meta);
  console.log("after global pipe:", JSON.stringify(afterGlobal));
  try { const out = await handlerPipe.transform(afterGlobal, meta); console.log("handler pipe ACCEPTED:", JSON.stringify(out)); }
  catch (e) { console.log("handler pipe rejected:", e.message); }
  try { await handlerPipe.transform({ title: "x", roomId: "r" }, meta); console.log("alone ACCEPTED"); }
  catch (e) { console.log("handler pipe alone rejected:", JSON.stringify(e.getResponse().message)); }
})();'
